async function main(){
  const mediaPage = figma.root.children.find(p=>p.id==="1:4");
  const ws = figma.root.children.find(p=>p.id==="50:2");
  let assets = ws.children.find(c=>c.name==="Assets (cloned)");
  if(!assets){ assets = figma.createFrame(); assets.name="Assets (cloned)"; assets.x=0; assets.y=4600; ws.appendChild(assets); }

  const wanted = ["Splash_Burger_Stack","Burger_Cheeseburger_Wendys","Burger_Veggie","Burger_Chicken","Burger_Fried_Chicken","Burger_Exploded_Custom","Topping_Tomato","Topping_Onions","Topping_Pickles","Topping_Bacon","Topping_Cheese","Topping_Mushroom","Topping_Avocado","Side_Fries","Side_Coleslaw","Side_Salad","Side_Onion_Rings","Side_Mozzarella_Sticks","Card_Mastercard","Card_Visa"];

  const found = [];
  function walk(node, depth){
    for(const c of node.children){
      const n = c.name;
      if(wanted.includes(n)){
        found.push(c);
        continue; // don't descend inside a matched asset
      }
      if(("children" in c) && c.children.length) walk(c, depth+1);
    }
  }
  walk(mediaPage, 0);
  console.log("found count="+found.length);
  const added = [];
  for(const c of found){
    const clone = c.clone();
    // Place assets in a row below existing
    clone.x = added.length*230;
    clone.y = 0;
    assets.appendChild(clone);
    added.push(c.name);
  }
  console.log("added="+added.join(","));
}
