    t.textAutoResize="WIDTH"; t.x=x; t.y=y; parent.appendChild(t); return t;
  }
  function R(parent,x,y,w,h,color,radius){
    const n=figma.createRectangle(); n.x=x;n.y=y;n.resize(w,h);
    n.fills=[{type:"SOLID",color:color}]; n.cornerRadius=radius||0; parent.appendChild(n); return n;
  }
  function IC(parent,srcId,x,y,size,color){
    const icon=figma.getNodeById(srcId).clone();
    const s=size/icon.width; icon.resize(icon.width*s,icon.height*s);
    icon.x=x;icon.y=y;parent.appendChild(icon);return icon;
  }
  function putImage(parent,name,x,y,w,h){
    const n=findImg(name); if(!n) return false;
    const c=n.clone();
    const scale=Math.min(w/c.width,h/c.height);
    c.resize(c.width*scale,c.height*scale);
    c.x=x+(w-c.width*scale)/2; c.y=y+(h-c.height*scale)/2;
