async function main(){
  const log=[];
  // Clean reference pages to original single-frame structure
  const keepByPage = {
    "0:1":"2:2",
    "1:2":"1:410",
    "1:3":"1:467",
    "1:4":"1:178"
  };
  for(const pid in keepByPage){
    const page = figma.root.children.find(p=>p.id===pid);
    if(!page){ log.push("NO PAGE "+pid); continue; }
    await figma.setCurrentPageAsync(page);
    const keepId = keepByPage[pid];
    for(const c of Array.from(page.children)){
      if(c.id !== keepId){
        log.push("removed:"+pid+":"+c.id+":"+c.type+":"+c.name);
        c.remove();
      } else {
        log.push("kept:"+pid+":"+c.id+":"+c.name);
      }
    }
  }
  throw new Error("CLEAN_OK ["+log.join(" | ")+"]");
}
