async function main(){
  await figma.loadFontAsync({family:"Roboto", style:"Regular"});
  // Load workspace page
  const ws = figma.root.children.find(p=>p.id==="50:2");
  await figma.setCurrentPageAsync(ws);
  // Get Assets frame reference (empty it)
  let assets = ws.children.find(c=>c.name==="Assets");
  if(assets){ Array.from(assets.children).forEach(x=>x.remove()); }
  // Load media page
  const md = figma.root.children.find(p=>p.id==="1:4");
  await figma.setCurrentPageAsync(md);
  // recursively collect nodes with IMAGE fills under media page
  const imgNodes=[];
  (function collect(n){
    if(n.children){ n.children.forEach(collect); }
    else if(n.type==="RECTANGLE" && n.fills && n.fills.some(f=>f.type==="IMAGE")){ imgNodes.push(n); }
  })(md);
  let x=0,y=0;
  for(const n of imgNodes){
    const c=n.clone();
    c.x=x; c.y=y;
    c.name="asset_"+n.name;
    assets.appendChild(c);
    x+=Math.max(c.width,80)+10;
    if(x>4200){x=0;y+=180;}
  }
  // switch back to ws so it's loaded
  await figma.setCurrentPageAsync(ws);
  throw new Error("CLONED "+imgNodes.length);
}
