async function main(){
  // 1. Switch to media page and capture live refs to the assets we need
  const md = figma.root.children.find(p=>p.id==="1:4");
  await figma.setCurrentPageAsync(md);
  const refs = [];
  const names = [
    "Splash_Burger_Stack","Burger_Cheeseburger_Wendys","Burger_Veggie","Burger_Chicken",
    "Burger_Fried_Chicken","Burger_Exploded_Custom",
    "Topping_Tomato","Topping_Onions","Topping_Pickles","Topping_Bacon","Topping_Cheese",
    "Topping_Mushroom","Topping_Avocado",
    "Side_Fries","Side_Coleslaw","Side_Salad","Side_Onion_Rings","Side_Mozzarella_Sticks",
    "Card_Mastercard","Card_Visa",
    "Avatar_Neutral"
  ];
  function findFirst(n, name){
    if(n.name===name) return n;
    if(n.children){ for(const c of n.children){ const r=findFirst(c,name); if(r) return r; } }
    return null;
  }
  for(const nm of names){
    const f = findFirst(md, nm);
    if(f) refs.push(f); else console.log("NOTFOUND "+nm);
  }

  // 2. Switch to workspace; workspace tree now loaded
  const ws = figma.root.children.find(p=>p.id==="50:2");
  await figma.setCurrentPageAsync(ws);

  // 3. Find or create Assets frame
  let assets = ws.children.find(c=>c.name==="Assets");
  if(!assets){ assets=figma.createFrame(); assets.name="Assets"; assets.resize(4350,400); ws.appendChild(assets); }
  Array.from(assets.children).forEach(c=>c.remove());

  // 4. Clone each captured media ref into Assets
  let count=0;
  for(const r of refs){
    const c = r.clone();
    assets.appendChild(c);
    count++;
  }
  assets.resize(4350, 200 + Math.max(1,count)*140);
}
main();

