    Minus:"1:393", Check:"1:398", Menu:"1:404"
  };
  const clones = [];
  for(const key in iconIds){
    const n = figma.getNodeById(iconIds[key]);
    if(n){
      const c = n.clone();
      c.name = "ic_"+key;
      clones.push(c);
    }
  }

  // switch back to ws and append
